<script setup>defineProps({sources:{type:Array,default:()=>[]}});const safe=url=>{try{return ['http:','https:'].includes(new URL(url).protocol)}catch{return false}}</script><template><div class="sources"><p v-if="!sources.length" class="quiet">暂未提供可核查的资料来源。</p><ol v-else><li v-for="(s,i) in sources" :key="i"><a v-if="safe(s.url)" :href="s.url" target="_blank" rel="noopener noreferrer">{{s.title||'资料来源'}}</a><span v-else>{{s.title||'资料来源'}}</span><p v-if="s.excerpt">{{s.excerpt}}</p></li></ol></div></template>
